NORMAL_PROFILE = 'pilot'

import json
import os
from pathlib import Path
import sys
import time

from arc_program_runtime import Config, LocalClient, ProgramSolver, Reply, atomic_json, score_selected, validate_submission
from arc_reasoning_setup import capture_server_metrics, check_gpu_hardware, discover_model, install_runtime, probe_model_configuration, start_server, stop_server

HIDDEN = os.environ.get("KAGGLE_IS_COMPETITION_RERUN", "").lower() in {"1", "true"}
PROFILE = "full" if HIDDEN else NORMAL_PROFILE
OUT = Path("/kaggle/working") if Path("/kaggle/working").exists() else Path.cwd()
INPUT = Path(os.environ.get("ARC_INPUT_ROOT", "/kaggle/input"))
START = time.monotonic()
# The commit deadline includes offline installation, compilation and scoring.
BUDGET_SECONDS = 11.7 * 3600 if HIDDEN else (150 * 60 if PROFILE == "full" else 100 * 60)
GLOBAL_END = START + BUDGET_SECONDS

if PROFILE == "verify":
    # Exercise subprocess execution, multiple test inputs and JSON packaging.
    # These artificial tasks and replies are never a competitive score.
    challenges = {
        "synthetic_identity": {"train": [{"input": [[1,0]], "output": [[1,0]]}], "test": [{"input": [[2]]}, {"input": [[3,4]]}]},
        "synthetic_flip": {"train": [{"input": [[1,2]], "output": [[2,1]]}], "test": [{"input": [[3,4,5]]}]},
    }
    class SyntheticClient:
        def generate(self, messages, max_tokens, deadline, seed, thinking=True):
            prompt = messages[1]["content"]
            source = "def transform(grid):\n    return [row[::-1] for row in grid]" if '"output":[[2,1]]' in prompt else "def transform(grid):\n    return grid"
            return Reply(content="```python\n" + source + "\n```", tokens=20, finish="stop")
    solver = ProgramSolver(SyntheticClient(), Config(workers=2, max_repairs=0), OUT, time.monotonic()+60)
    submission, metrics = solver.solve(challenges)
    validate_submission(submission, challenges)
    assert metrics["train_verified_tasks"] == 2, metrics
    assert submission["synthetic_flip"][0]["attempt_1"] == [[5,4,3]]
    atomic_json(OUT / "verification.json", {"synthetic_only": True, "passed": True, "model_inference_tested": False})
    print("CPU synthetic verification passed; model accuracy and GPU startup remain untested.")
elif PROFILE == "envcheck":
    import shutil
    try:
        model = discover_model(INPUT)
        environment = install_runtime(INPUT, Path("/tmp/arc_runtime"), time.monotonic()+900)
        probe = probe_model_configuration(model, Path("/tmp/arc_runtime"))
        atomic_json(OUT / "environment_probe.json", {"passed": True, "model_inference_tested": False, "environment": environment, **probe})
        print("Offline dependency, model configuration and reasoning-template probes passed. GPU inference remains untested.")
    finally:
        if Path("/tmp/arc_pip_install.log").exists():
            shutil.copyfile("/tmp/arc_pip_install.log", OUT / "arc_pip_install.log")
else:
    name = "arc-agi_test_challenges.json" if HIDDEN else "arc-agi_evaluation_challenges.json"
    matches = list(INPUT.rglob(name))
    if len(matches) != 1:
        raise FileNotFoundError(f"Expected exactly one competition challenge file {name}, found {matches}")
    challenge_path = matches[0]
    challenges = json.loads(challenge_path.read_text())
    solver = ProgramSolver(LocalClient(), Config(), OUT, GLOBAL_END - 180)
    # Keep a complete valid artifact even if setup or model startup fails.
    solver.save(challenges, START, "before_setup", [])
    process = None
    try:
        atomic_json(OUT / "submission_status.json", {"status": "fallback_only", "ready_for_submission": False, "model_inference_started": False})
        check_gpu_hardware(OUT)
        model = discover_model(INPUT)
        environment = install_runtime(INPUT, Path("/tmp/arc_runtime"), GLOBAL_END - 900)
        process, receipt = start_server(model, Path("/tmp/arc_runtime"), OUT, min(GLOBAL_END - 600, time.monotonic()+1200))
        atomic_json(OUT / "environment_receipt.json", {**receipt, "environment": environment, "profile": PROFILE, "hidden": HIDDEN})
        limit = 16 if PROFILE == "pilot" else None
        submission, metrics = solver.solve(challenges, limit=limit)
        receipt.update(capture_server_metrics(OUT))
        atomic_json(OUT / "environment_receipt.json", {**receipt, "environment": environment, "profile": PROFILE, "hidden": HIDDEN})
        if metrics["model_attempted_tasks"] != len(metrics["selected_tasks"]):
            raise RuntimeError("Incomplete model coverage; inspect run_metrics.json before promotion")
        if metrics["train_verified_tasks"] == 0:
            raise RuntimeError("No demonstration-verified program; fallback output must not be promoted")
        atomic_json(OUT / "submission_status.json", {"status": "inference_complete", "ready_for_submission": HIDDEN, "model_inference_started": True, "profile": PROFILE, "train_verified_tasks": metrics["train_verified_tasks"]})
    except Exception as exc:
        import traceback
        atomic_json(OUT / "startup_failure.json", {"type": type(exc).__name__, "message": str(exc), "traceback": traceback.format_exc()})
        atomic_json(OUT / "submission_status.json", {"status": "failed", "ready_for_submission": False, "model_inference_started": bool(solver.metrics["requests"]), "error": str(exc)})
        raise
    finally:
        import shutil
        if Path("/tmp/arc_pip_install.log").exists():
            shutil.copyfile("/tmp/arc_pip_install.log", OUT / "arc_pip_install.log")
        if process is not None:
            stop_server(process)
    # Evaluation labels are accessed only after inference and server shutdown.
    if not HIDDEN:
        solution_path = challenge_path.with_name("arc-agi_evaluation_solutions.json")
        solutions = json.loads(solution_path.read_text())
        report = score_selected(submission, challenges, solutions, metrics["selected_tasks"])
        atomic_json(OUT / "evaluation_report.json", report)
        print(json.dumps(report, indent=2))
        if PROFILE == "pilot":
            print("16-task pilot only. This is not a full-validation or leaderboard score.")
print("Output:", OUT / ("environment_probe.json" if PROFILE == "envcheck" else "submission.json"))
